<?php
namespace App\Http\Controllers\Admin;
use App\Http\Controllers\Controller; use App\Models\MediaAsset; use App\Services\{AdminAudit,MediaVariantGenerator}; use Illuminate\Http\Request; use Illuminate\Support\Facades\Storage;
class MediaLibraryController extends Controller { public function index(Request $r){$q=MediaAsset::query()->withCount('variants');if($r->filled('q'))$q->where('alt_text','like','%'.$r->q.'%');return view('admin.media.index',['assets'=>$q->latest()->paginate(30)->withQueryString()]);}public function store(Request $r,MediaVariantGenerator $variants,AdminAudit $audit){$d=$r->validate(['file'=>'required|file|image|mimetypes:image/jpeg,image/png,image/webp|max:10240','alt_text'=>'nullable|string|max:255','caption'=>'nullable|string|max:1000']);$file=$d['file'];$info=@getimagesize($file->getRealPath());abort_unless($info&&in_array($info['mime'],['image/jpeg','image/png','image/webp'],true),422);$checksum=hash_file('sha256',$file->getRealPath());$asset=MediaAsset::where('checksum',$checksum)->first();if(!$asset){$path='media/originals/'.$checksum.'.'.($file->extension()?:'bin');Storage::disk(config('legacy-media.disk'))->put($path,file_get_contents($file->getRealPath()));$asset=MediaAsset::create(['original_path'=>$path,'mime'=>$info['mime'],'width'=>$info[0],'height'=>$info[1],'bytes'=>$file->getSize(),'checksum'=>$checksum,'alt_text'=>$d['alt_text']??null,'caption'=>$d['caption']??null]);$variants->generate($asset);}$audit->record('media.uploaded',$asset);return back()->with('status','Média importé.');}public function update(Request $r,MediaAsset $asset,AdminAudit $audit){$d=$r->validate(['alt_text'=>'nullable|string|max:255','caption'=>'nullable|string|max:1000']);$asset->update($d);$audit->record('media.updated',$asset,$d);return back()->with('status','Média enregistré.');}}
